`timescale 1ns/1ps
// AUTO-GENERATED by hls.py: board-level self-checking testbench for top.v
// Uses only the board pins: BTNC = step, BTNU = load, SW, LED, 7-segment display.
module testbench;
    parameter W = 16;
    reg clk = 0, resetn = 1, btnc = 0, btnu = 0;
    reg [15:0] sw = 0;
    wire [15:0] led; wire [7:0] an; wire ca, cb, cc, cd, ce, cf, cg, dp;
    top #(.W(W), .DEBOUNCE_CYCLES(4), .REFRESH_BITS(1)) dut (
        .CLK100MHZ(clk), .CPU_RESETN(resetn), .BTNC(btnc), .BTNU(btnu), .SW(sw), .LED(led),
        .CA(ca), .CB(cb), .CC(cc), .CD(cd), .CE(ce), .CF(cf), .CG(cg), .DP(dp), .AN(an));
    always #5 clk = ~clk;

    // ---- read the multiplexed display the way a person would: one digit at a time ----
    function [3:0] hex_of(input [6:0] s);   // s = {g,f,e,d,c,b,a}, active low
        case (s)
            7'b1000000: hex_of = 4'h0;
            7'b1111001: hex_of = 4'h1;
            7'b0100100: hex_of = 4'h2;
            7'b0110000: hex_of = 4'h3;
            7'b0011001: hex_of = 4'h4;
            7'b0010010: hex_of = 4'h5;
            7'b0000010: hex_of = 4'h6;
            7'b1111000: hex_of = 4'h7;
            7'b0000000: hex_of = 4'h8;
            7'b0010000: hex_of = 4'h9;
            7'b0001000: hex_of = 4'hA;
            7'b0000011: hex_of = 4'hB;
            7'b1000110: hex_of = 4'hC;
            7'b0100001: hex_of = 4'hD;
            7'b0000110: hex_of = 4'hE;
            7'b0001110: hex_of = 4'hF;
            default: hex_of = 4'hx;
        endcase
    endfunction
    reg [31:0] disp = 0;   // [31:16] = variable view, [15:0] = functional unit view
    integer d;
    always @(posedge clk)
        for (d = 0; d < 8; d = d + 1)
            if (!an[d]) disp[d*4 +: 4] <= hex_of({cg, cf, ce, cd, cc, cb, ca});

    integer errors = 0, checks = 0;
    task press_step; begin   // bounce a little, then hold, then release
        btnc = 1; #7 btnc = 0; #13 btnc = 1; repeat (12) @(posedge clk);
        #1 btnc = 0; #9 btnc = 1; #6 btnc = 0; repeat (12) @(posedge clk); #1; end
    endtask
    task press_load; begin
        btnu = 1; #7 btnu = 0; #13 btnu = 1; repeat (12) @(posedge clk);
        #1 btnu = 0; repeat (12) @(posedge clk); #1; end
    endtask
    task do_reset; begin resetn = 0; repeat (4) @(posedge clk); #1 resetn = 1; repeat (4) @(posedge clk); #1; end endtask
    task show; begin repeat (40) @(posedge clk); #1; end endtask   // let the display scan all digits
    task check(input [31:0] got, input [31:0] exp, input [255:0] nm);
        begin checks = checks + 1; if (got !== exp) begin errors = errors + 1;
            $display("FAIL %0s: got %0d expected %0d", nm, got, exp); end end
    endtask

    initial begin
        // ================= run 0: reset defaults (A=5, B=3) =================
        do_reset;
        check(led[14], 1, "IDLE led after reset");
        press_step;   // -> cycle 1
        check(led[4:0], 1, "state led");
        sw[15:12] = 4'd0; show; check(disp[15:0], 8, "add0 computing X_1");
        press_step;   // -> cycle 2
        check(led[4:0], 2, "state led");
        sw[15:12] = 4'd0; show; check(disp[15:0], 13, "add0 computing Y_1");
        sw[15:12] = 4'd1; show; check(disp[15:0], 5, "sub0 computing Z_1");
        press_step;   // -> cycle 3
        check(led[4:0], 3, "state led");
        sw[15:12] = 4'd2; show; check(disp[15:0], 15, "mul0 computing Q_1");
        press_step;   // -> DONE
        check(led[15], 1, "DONE led");
        sw[11:8] = 4'd0; show; check(disp[31:16], 5, "register A");
        sw[11:8] = 4'd1; show; check(disp[31:16], 3, "register B");
        sw[11:8] = 4'd2; show; check(disp[31:16], 8, "register X_1");
        sw[11:8] = 4'd3; show; check(disp[31:16], 13, "register Y_1");
        sw[11:8] = 4'd4; show; check(disp[31:16], 5, "register Z_1");
        sw[11:8] = 4'd5; show; check(disp[31:16], 15, "register Q_1");
        sw[11:8] = 4'd0; sw[7:0] = 8'd250; repeat (4) @(posedge clk); press_load; show;
        check(disp[31:16], 5, "LOAD ignored when not IDLE");
        press_step;   // DONE -> IDLE
        check(led[4:0], 0, "back to IDLE");
        // ================= run 1: inputs loaded from SW[7:0] with BTNU (A=121, B=7) =================
        do_reset;
        check(led[14], 1, "IDLE led after reset");
        sw[11:8] = 4'd0; sw[7:0] = 8'd121; repeat (4) @(posedge clk); press_load;   // A
        sw[11:8] = 4'd1; sw[7:0] = 8'd7; repeat (4) @(posedge clk); press_load;   // B
        press_step;   // -> cycle 1
        check(led[4:0], 1, "state led");
        sw[15:12] = 4'd0; show; check(disp[15:0], 128, "add0 computing X_1");
        press_step;   // -> cycle 2
        check(led[4:0], 2, "state led");
        sw[15:12] = 4'd0; show; check(disp[15:0], 249, "add0 computing Y_1");
        sw[15:12] = 4'd1; show; check(disp[15:0], 121, "sub0 computing Z_1");
        press_step;   // -> cycle 3
        check(led[4:0], 3, "state led");
        sw[15:12] = 4'd2; show; check(disp[15:0], 847, "mul0 computing Q_1");
        press_step;   // -> DONE
        check(led[15], 1, "DONE led");
        sw[11:8] = 4'd0; show; check(disp[31:16], 121, "register A");
        sw[11:8] = 4'd1; show; check(disp[31:16], 7, "register B");
        sw[11:8] = 4'd2; show; check(disp[31:16], 128, "register X_1");
        sw[11:8] = 4'd3; show; check(disp[31:16], 249, "register Y_1");
        sw[11:8] = 4'd4; show; check(disp[31:16], 121, "register Z_1");
        sw[11:8] = 4'd5; show; check(disp[31:16], 847, "register Q_1");
        sw[11:8] = 4'd0; sw[7:0] = 8'd134; repeat (4) @(posedge clk); press_load; show;
        check(disp[31:16], 121, "LOAD ignored when not IDLE");
        press_step;   // DONE -> IDLE
        check(led[4:0], 0, "back to IDLE");
        if (errors == 0) $display("PASS: %0d board-level checks correct", checks);
        else $display("FAILED with %0d errors (of %0d checks)", errors, checks);
        $finish;
    end
endmodule
